def main():
 for x in 'ABC':
  folder=J/'screenshots'/x;files=sorted(folder.glob('*.png'));rows=[]
  for p in files:
   if p.name.startswith('animation-'):
    note=pair('Genuine sample in the special-move sequence: compare body anticipation, arm extension, projectile formation and recovery with the adjacent frames; no pose was set directly.','Mẫu thật trong chuỗi special: đối chiếu lấy đà, tay duỗi, projectile hình thành và recovery với frame kế bên; không gán pose trực tiếp.')
   else:
    idx=int(p.name[:2])-1;note=pair(*notes[x][idx])
   rows.append({'image':p.name,'sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'reviewed':True,'note':note})
  out={'project':x,'method':'All final original images viewed through image-reader contact sheets, with individual critical screens also opened. Manual visual notes; no submitted screenshots used.','criteria':['legibility','alignment','hierarchy','consistency','contrast/glow','clipping/overlaps','visual defects','designed versus placeholder appearance'],'images':rows}
  (J/'logs'/x/'visual-review.json').write_text(json.dumps(out,ensure_ascii=False,indent=2),encoding='utf-8')
 print('Manual bilingual visual notes and image fingerprints saved.')
if __name__=='__main__':main()
